param([parameter(mandatory=$true)][string]$baseline,[parameter(mandatory=$true)][string]$post)
$erroractionpreference='stop'
function get-column($rows,[string[]]$names){if(-not $rows -or $rows.count -eq 0){return $null};$props=$rows[0].psobject.properties.name;foreach($n in $names){$hit=$props|where-object{$_ -ieq $n}|select-object -first 1;if($hit){return $hit}};return $null}
function mean([double[]]$v){if(-not $v -or $v.Count -eq 0){return $null};(($v|measure-object -average).average)}
function stddev([double[]]$v){if(-not $v -or $v.Count -lt 2){return 0};$avg=mean $v;$sum=0.0;foreach($x in $v){$sum += [math]::Pow(($x-$avg),2)};[math]::Sqrt($sum/($v.Count-1))}
function median([double[]]$v){if(-not $v -or $v.Count -eq 0){return $null};$s=@($v|sort-object);$n=$s.Count;if(($n%2)-eq 1){return [double]$s[[int][math]::Floor($n/2)]};(([double]$s[$n/2-1]+[double]$s[$n/2])/2)}
function read-metrics($path){
  $rows=@(import-csv -literalpath $path);if($rows.count -lt 100){throw "poucos registros em $path (minimo 100)"}
  $col=get-column $rows @('frametime','frametimems','msbetweenpresents','msbetweendisplaychange');if(-not $col){throw "coluna de frametime nao encontrada em $path"}
  $ms=New-Object System.Collections.Generic.List[double]
  foreach($r in $rows){$v=0.0;$raw=[string]$r.$col;if([double]::tryparse($raw,[globalization.numberstyles]::float,[globalization.cultureinfo]::invariantculture,[ref]$v)-and $v -gt 0 -and $v -lt 1000){$ms.Add($v)}}
  if($ms.count -lt 100){throw "poucos frametimes validos em $path"}
  $fps=@($ms|foreach-object{1000.0/$_});$fpssorted=@($fps|sort-object);$mssorted=@($ms|sort-object);$onen=[math]::max(1,[int][math]::ceiling($fps.count*.01));$zeroonen=[math]::max(1,[int][math]::ceiling($fps.count*.001));$p99n=[math]::max(1,[int][math]::ceiling($ms.count*.99));$avgms=mean $ms;$sdms=stddev $ms
  [pscustomobject]@{avgfps=[math]::round((mean $fps),2);low1=[math]::round((mean @($fpssorted|select-object -first $onen)),2);low01=if($fps.count -ge 1000){[math]::round((mean @($fpssorted|select-object -first $zeroonen)),2)}else{$null};avgframetimems=[math]::round($avgms,2);medianframetimems=[math]::round((median $ms),2);frametimestddevms=[math]::round($sdms,3);frametimecvpercent=if($avgms -gt 0){[math]::round(($sdms/$avgms)*100,2)}else{0};p99frametimems=[math]::round($mssorted[$p99n-1],2);maxframetimems=[math]::round((($ms|measure-object -maximum).maximum),2);frames=$fps.count}
}
function safepct([double]$a,[double]$b){if($a -eq 0){return 0};[math]::round((($b/$a)-1)*100,2)}
$b=read-metrics $baseline;$p=read-metrics $post
$metrics=@([pscustomobject]@{metric='avgfps';baseline=$b.avgfps;post=$p.avgfps;delta=[math]::round($p.avgfps-$b.avgfps,2);percent=(safepct $b.avgfps $p.avgfps);weight=40;lowerisbetter=$false},[pscustomobject]@{metric='1% low';baseline=$b.low1;post=$p.low1;delta=[math]::round($p.low1-$b.low1,2);percent=(safepct $b.low1 $p.low1);weight=25;lowerisbetter=$false},[pscustomobject]@{metric='0.1% low';baseline=$b.low01;post=$p.low01;delta=if($null -ne $b.low01 -and $null -ne $p.low01){[math]::round($p.low01-$b.low01,2)}else{$null};percent=if($null -ne $b.low01 -and $null -ne $p.low01){safepct $b.low01 $p.low01}else{0};weight=10;lowerisbetter=$false},[pscustomobject]@{metric='frametime P99';baseline=$b.p99frametimems;post=$p.p99frametimems;delta=[math]::round($p.p99frametimems-$b.p99frametimems,2);percent=(safepct $b.p99frametimems $p.p99frametimems);weight=15;lowerisbetter=$true},[pscustomobject]@{metric='frametime CV';baseline=$b.frametimecvpercent;post=$p.frametimecvpercent;delta=[math]::round($p.frametimecvpercent-$b.frametimecvpercent,2);percent=(safepct $b.frametimecvpercent $p.frametimecvpercent);weight=10;lowerisbetter=$true})
$score=0.0;foreach($m in $metrics){$direction=if($m.lowerisbetter){-1}else{1};$score += ([double]$m.percent*$direction)*([double]$m.weight/100)}
$frameDeltaPercent=[math]::round((([math]::Abs($p.frames-$b.frames)/[math]::Max(1,$b.frames))*100),2);$qualityIssues=New-Object System.Collections.Generic.List[string]
if($frameDeltaPercent -gt 20){$qualityIssues.Add("diferenca de frames $frameDeltaPercent%")};if($p.frametimecvpercent -gt ($b.frametimecvpercent*1.25)-and($p.frametimecvpercent-$b.frametimecvpercent)-gt 1){$qualityIssues.Add('variabilidade do frametime aumentou muito')};if($b.frames -lt 1000-or $p.frames -lt 1000){$qualityIssues.Add('0.1% low indisponível por baixa amostra')}
$severe=@($metrics|where-object{if($_.lowerisbetter){$_.percent-ge 5}else{$_.percent-le -5}}).count -gt 0;$decision=if($severe -or $score -lt -1){'ROLLBACK'}elseif($score -ge 1 -and -not $qualityIssues.Count){'KEEP'}else{'RETEST'};$confidence=[math]::Min(99,[math]::Round(55+[math]::Min(20,$b.frames/500)+[math]::Min(15,$p.frames/500)+$(if(-not $qualityIssues.Count){10}else{0}),0))
$legacy=if($decision -eq 'KEEP'){'decisao=keep'}elseif($decision -eq 'ROLLBACK'){'decisao=rollback_recommended'}else{'decisao=retest'};Write-Output $legacy;[pscustomobject]@{timestamp=(get-date).ToString('o');decision=$decision;score=[math]::round($score,2);baseline=$b;post=$p;metrics=$metrics;framecountdeltapercent=$frameDeltaPercent;qualityissues=@($qualityIssues);confidence=$confidence;severeregression=$severe}|convertto-json -depth 8
